 p.compare(native.ggml_dup_tensor(p.nc,a),goose.ggml_dup_tensor(p.gc,b));p.compare(native.ggml_view_tensor(p.nc,a),goose.ggml_view_tensor(p.gc,b));p.compare(native.ggml_reshape_1d(p.nc,a,48*bs),goose.ggml_reshape_1d(p.gc,b,48*bs));auto r2n=native.ggml_reshape_2d(p.nc,a,4*bs,12),r2g=goose.ggml_reshape_2d(p.gc,b,4*bs,12);p.compare(r2n,r2g);p.compare(native.ggml_reshape(p.nc,a,r2n),goose.ggml_reshape(p.gc,b,r2g));p.compare(native.ggml_reshape_3d(p.nc,a,4*bs,3,4),goose.ggml_reshape_3d(p.gc,b,4*bs,3,4));p.compare(native.ggml_reshape_4d(p.nc,a,4*bs,2,3,2),goose.ggml_reshape_4d(p.gc,b,4*bs,2,3,2));
