 p.compare(native.ggml_view_2d(p.nc,a,bs,2,a->nb[1],0),goose.ggml_view_2d(p.gc,b,bs,2,b->nb[1],0));p.compare(native.ggml_view_3d(p.nc,a,bs,2,2,a->nb[1],a->nb[2],0),goose.ggml_view_3d(p.gc,b,bs,2,2,b->nb[1],b->nb[2],0));p.compare(native.ggml_view_4d(p.nc,a,bs,2,1,2,a->nb[1],a->nb[2],a->nb[3],0),goose.ggml_view_4d(p.gc,b,bs,2,1,2,b->nb[1],b->nb[2],b->nb[3],0));
 std::array<int,4> axes={0,1,2,3};do{p.compare(native.ggml_permute(p.nc,a,axes[0],axes[1],axes[2],axes[3]),goose.ggml_permute(p.gc,b,axes[0],axes[1],axes[2],axes[3]));}while(std::next_permutation(axes.begin(),axes.end()));p.compare(native.ggml_transpose(p.nc,a),goose.ggml_transpose(p.gc,b));
 for(int64_t index:{INT64_C(0),INT64_C(1),24*bs,48*bs-1}){int64_t x[4]={},y[4]={};native.ggml_unravel_index(a,index,x,x+1,x+2,x+3);goose.ggml_unravel_index(b,index,y,y+1,y+2,y+3);require(std::memcmp(x,y,sizeof x)==0,"unravel index");native.ggml_unravel_index(a,index,nullptr,x+1,nullptr,x+3);goose.ggml_unravel_index(b,index,nullptr,y+1,nullptr,y+3);require(x[1]==y[1]&&x[3]==y[3],"optional unravel outputs");}
 int64_t empty[4]={0,2,1,1};p.compare(native.ggml_new_tensor(p.nc,ty,4,empty),goose.ggml_new_tensor(p.gc,ty,4,empty));
